import hashlib,json,os,statistics,subprocess,tempfile,time
from pathlib import Path
os.sched_setaffinity(0,{0})
binaries={k:str(Path(v).resolve()) for k,v in {'parent':'build/review-j10/release/mus-solver','candidate':'build/review-j11/release/mus-solver'}.items()}
output=Path('/tmp/mus-review-j11-performance.json')
data={'parent_commit':'d293c57','method':'CLI diagnostic metadata only. Compare library and bot bytes, numeric evaluation fields in both affected generic formats; unchanged root routes are covered by existing CLI tests and identical library bytes, and one/two-mus ordago variants. Amplify the changed output path with 1000 fresh CLI evaluations per timed batch, three alternating pairs, CPU0. Gate 20% time or 25% RSS followed by five confirmation pairs. No concurrent own build/test work.','runs':[],'summary':[],'validation':[],'hashes':{}}
for version,binary in binaries.items():
 data['hashes'][version]={name:hashlib.sha256((Path(binary).parent/name).read_bytes()).hexdigest() for name in ['libmus_solver.a','mus-bot','mus-solver']}
for name in ['libmus_solver.a','mus-bot']:assert data['hashes']['parent'][name]==data['hashes']['candidate'][name]
extras={'deals':'2','opponent_cards':'fixed','best_responses':'per-deal','root_bound':'none'}
def metrics(command):
 stdout=subprocess.check_output(command,text=True)
 line=next(l for l in stdout.splitlines() if l.startswith('evaluation '))
 return dict(token.split('=',1) for token in line.split()[1:])
for variant in ['ordago','ordago-public']:
 args=['--format',variant,'--evaluate']
 a=metrics([binaries['parent'],*args]);b=metrics([binaries['candidate'],*args])
 if variant in ('ordago','ordago-public'):
  for k,v in extras.items():assert b.pop(k)==v
 assert a==b
 data['validation'].append({'muses':1,'format':variant,'same_original_fields':True,'metrics':a})
for variant in ['ordago','ordago-public']:
 a=metrics([str(Path('build/review-j10-two/debug/mus-solver').resolve()),'--format',variant,'--evaluate'])
 b=metrics([str(Path('build/review-j11-two/debug/mus-solver').resolve()),'--format',variant,'--evaluate'])
 for k,v in extras.items():assert b.pop(k)==v
 assert a==b
 data['validation'].append({'muses':2,'format':variant,'same_original_fields':True,'metrics':a})

def save():output.write_text(json.dumps(data,indent=2)+'\n')
def batch(group,version,repeat):
 command=[binaries[version],'--format',group,'--evaluate']
 with tempfile.TemporaryFile(mode='w+') as log:
  start=time.perf_counter();rss=0
  for _ in range(1000):
   pid=os.posix_spawn(command[0],command,os.environ,file_actions=[(os.POSIX_SPAWN_DUP2,log.fileno(),1),(os.POSIX_SPAWN_DUP2,log.fileno(),2)])
   _,status,usage=os.wait4(pid,0);rss=max(rss,usage.ru_maxrss)
   if status:log.seek(0);raise RuntimeError(log.read())
  elapsed=time.perf_counter()-start
 row={'group':group,'version':version,'repeat':repeat,'calls':1000,'command':command,'wall_seconds':elapsed,'peak_rss_kib':rss}
 data['runs'].append(row);save();print(row,flush=True)
def summary(group,confirmation=False):
 rows=[r for r in data['runs'] if r['group']==group and (r['repeat']>3)==confirmation]
 s={'group':group,'confirmation':confirmation}
 for field in ['wall_seconds','peak_rss_kib']:
  a=statistics.median(r[field] for r in rows if r['version']=='parent');b=statistics.median(r[field] for r in rows if r['version']=='candidate')
  s[field]={'parent':a,'candidate':b,'change_percent':100*(b/a-1)}
 s['gate_triggered']=s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25
 data['summary'].append(s);save();print(s,flush=True);return s['gate_triggered']
for group in ['ordago','ordago-public']:
 for repeat in range(1,4):
  for version in (['parent','candidate'] if repeat%2 else ['candidate','parent']):batch(group,version,repeat)
 if summary(group):
  for repeat in range(4,9):
   for version in (['parent','candidate'] if repeat%2 else ['candidate','parent']):batch(group,version,repeat)
  if summary(group,True):data['blocked']=True;save();break
else:data['blocked']=False;save()
